<form class="toolbar" method="get"><input type="search" name="q" value="<?= e($s) ?>" placeholder="Search name, skill, reference…"><select name="job" data-autosubmit><option value="">All vacancies</option><?php foreach ($jobs as $j): ?><option value="<?= (int) $j['id'] ?>" <?= $job == $j['id'] ? 'selected' : '' ?>><?= e($j['title']) ?></option><?php endforeach; ?></select><select name="stage" data-autosubmit><option value="">All stages</option><?php foreach (ATS_STAGES as $x): ?><option <?= $stage === $x ? 'selected' : '' ?>><?= $x ?></option><?php endforeach; ?></select><select name="fit" data-autosubmit><option value="">Any fit</option><?php foreach ([40, 60, 75] as $f): ?><option value="<?= $f ?>" <?= $minFit == $f ? 'selected' : '' ?>><?= $f ?>%+ fit</option><?php endforeach; ?></select><label class="ck"><input type="checkbox" name="pool" value="1" <?= $pool ? 'checked' : '' ?> onchange="this.form.submit()"> Talent pool</label><span class="grow"></span><a class="btn btn-ghost btn-sm" href="<?= e(url('/admin/ats/applications', ['q' => $s, 'job' => $job, 'stage' => $stage, 'export' => 'csv'])) ?>"><?= icon('download', 15) ?> Export</a></form>
<form method="post" action="/admin/ats/applications/bulk"><?= csrf_field() ?>
<div class="toolbar"><select name="stage" style="min-width:150px"><?php foreach (ATS_STAGES as $x) { echo '<option>' . $x . '</option>'; } ?></select><input name="message" placeholder="Optional message to candidates" style="min-width:240px"><label class="ck"><input type="checkbox" name="notify" value="1"> Email candidates</label><button class="btn btn-ghost btn-sm" data-confirm="Move all selected applicants?">Move selected</button></div>
<div class="table-wrap"><table class="t"><thead><tr><th><input type="checkbox" onclick="document.querySelectorAll('.sel').forEach(c=>c.checked=this.checked)"></th><th>Candidate</th><th>Role</th><th>Stage</th><th>Fit</th><th>Rating</th><th>Applied</th></tr></thead><tbody>
<?php foreach ($items as $a): ?><tr><td><input type="checkbox" class="sel" name="ids[]" value="<?= (int) $a['id'] ?>"></td><td><a href="/admin/ats/application/<?= (int) $a['id'] ?>"><strong><?= e($a['name']) ?></strong></a><div class="muted xs"><?= e($a['email']) ?> · <?= e($a['phone']) ?></div></td><td class="small"><?= e($a['job_title'] ?: 'Talent network') ?></td><td><?= badge($a['stage'], ['Hired' => 'green', 'Offer' => 'green', 'Rejected' => 'red', 'Interview' => 'blue'][$a['stage']] ?? '') ?></td><td><span class="badge <?= $a['fit_score'] >= 70 ? 'green' : ($a['fit_score'] >= 40 ? 'amber' : '') ?>"><?= (int) $a['fit_score'] ?>%</span></td><td><?= $a['rating'] ? str_repeat('★', (int) $a['rating']) : '—' ?></td><td class="muted xs"><?= e(ago($a['created_at'])) ?></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="7" class="center muted" style="padding:30px">No applicants match.</td></tr><?php endif; ?></tbody></table></div></form><?= pager($pg, '/admin/ats/applications', ['q' => $s, 'job' => $job, 'stage' => $stage, 'fit' => $minFit, 'pool' => $pool]) ?>
